from review import card,save,DATE

def b(title,text,citation=None):
 d=dict(title=title,text=text)
 if citation:d['citation']=citation
 return d
def summary(sentences,refs):
 return dict(sentences=sentences,basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=refs)

