 dict(id='separation2024',title='Separations in Proof Complexity and TFNP',authors='Mika Göös, Alexandros Hollender, Siddhartha Jain, Gilbert Maystre, William Pires, Robert Robere, Ran Tao',year=2024,url='https://doi.org/10.1145/3663758',pdf_url='https://www.osti.gov/pages/servlets/purl/2582805',locator='JACM 71(4), article 26: Theorem 5 and Section 8.3 establish EOPL^dt not contained in UEOPL^dt; Section 2 explains the resulting oracle separation. This does not separate the ordinary circuit-defined classes.')
